// Generated by tools/build.mjs. Application cache and learning record have separate lifecycles.
const PREFIX="icu-atlas-shell:"+new URL(self.registration.scope).pathname+":",CACHE=PREFIX+"ab6787513790ed";
const FILES=["./","index.html","app.js","model.js","config.js","labs.js","walkthrough.js","curriculum.js","atlas.js","plates.js","illustrations.js","style.css","atlas.css","manifest.webmanifest","assets/cardio.webp","assets/heart.webp","assets/icon-180.png","assets/icon-192.png","assets/icon-512.png","assets/icon.svg","assets/neuro.webp","assets/resp.webp"];
self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting()))});
self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith(PREFIX)&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener("fetch",e=>{if(e.request.method!=="GET"||!e.request.url.startsWith(self.registration.scope))return;e.respondWith((async()=>{const c=await caches.open(CACHE);let hit=await c.match(e.request,{ignoreSearch:true});if(hit)return hit;try{return await fetch(e.request)}catch(err){if(e.request.mode==="navigate"){let page=await c.match("index.html");if(page)return page}throw err}})())});